using System;
using UnityEngine;
using Framework.CameraSystem;

namespace Game.Stage
{
    /// <summary>
    /// 迷路ステージの生成に合わせて
    /// カメラの表示範囲を自動調整するクラス。
    ///
    /// 実際のカメラ調整処理は
    /// GridCameraFitterへ委譲する。
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(Camera))]
    public class MazeStageCameraController : MonoBehaviour
    {
        #region Inspector Fields

        [Header("参照設定")]

        /// <summary>監視対象のステージ管理クラス。</summary>
        [SerializeField]
        [Tooltip("カメラ調整対象のステージ管理クラス")]
        private MazeStageManager stageManager;

        /// <summary>調整対象のカメラ。</summary>
        [SerializeField]
        [Tooltip("未設定の場合は同じGameObjectのCameraを使用")]
        private Camera targetCamera;

        [Header("カメラ設定")]

        /// <summary>迷路周囲に確保する余白。</summary>
        [SerializeField]
        [Min(0f)]
        [Tooltip("迷路の各辺に確保するワールド座標上の余白")]
        private float padding = 1f;

        /// <summary>ステージ生成時に自動調整するか。</summary>
        [SerializeField]
        [Tooltip("ステージ生成完了時にカメラを調整する")]
        private bool fitOnStageGenerated = true;

        /// <summary>画面比率変更時に再調整するか。</summary>
        [SerializeField]
        [Tooltip("画面のアスペクト比が変化した際に再調整する")]
        private bool fitOnAspectChanged = true;

        [Header("デバッグ設定")]

        /// <summary>カメラ調整結果をログへ出力するか。</summary>
        [SerializeField]
        [Tooltip("カメラ調整時に位置と表示サイズを出力する")]
        private bool printDebugLog = true;

        #endregion

        #region Runtime Fields

        /// <summary>前回調整時のアスペクト比。</summary>
        private float lastAspect = -1f;

        /// <summary>イベント登録先のステージ管理クラス。</summary>
        private MazeStageManager subscribedManager;

        #endregion

        #region Properties

        /// <summary>現在の調整対象カメラ。</summary>
        public Camera TargetCamera => targetCamera;

        /// <summary>現在の余白設定。</summary>
        public float Padding => padding;

        /// <summary>前回調整時のアスペクト比。</summary>
        public float LastAspect => lastAspect;

        #endregion

        #region Unity Methods

        /// <summary>コンポーネント生成時の処理。</summary>
        private void Awake()
        {
            // カメラが未設定の場合は自動取得する。
            if (targetCamera == null)
            {
                targetCamera = GetComponent<Camera>();
            }
        }

        /// <summary>コンポーネント有効化時の処理。</summary>
        private void OnEnable()
        {
            SubscribeStageEvents();

            // 既にステージが生成されている場合にも対応する。
            if (fitOnStageGenerated &&
                stageManager != null &&
                stageManager.HasStage)
            {
                FitCurrentStage();
            }
        }

        /// <summary>画面比率の変化を監視する。</summary>
        private void LateUpdate()
        {
            if (!fitOnAspectChanged ||
                targetCamera == null ||
                stageManager == null ||
                !stageManager.HasStage)
            {
                return;
            }

            float currentAspect = targetCamera.aspect;

            // アスペクト比が変化した場合のみ再計算する。
            if (!Mathf.Approximately(
                    lastAspect,
                    currentAspect))
            {
                FitCurrentStage();
            }
        }

        /// <summary>コンポーネント無効化時の処理。</summary>
        private void OnDisable()
        {
            UnsubscribeStageEvents();
        }

        /// <summary>Inspector設定値を検証する。</summary>
        private void OnValidate()
        {
            if (float.IsNaN(padding) ||
                float.IsInfinity(padding))
            {
                padding = 1f;
            }

            padding = Mathf.Max(0f, padding);
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// ステージ生成イベントを登録する。
        /// </summary>
        private void SubscribeStageEvents()
        {
            UnsubscribeStageEvents();

            if (stageManager == null)
            {
                Debug.LogWarning(
                    "カメラ調整対象のStageManagerが未設定です。",
                    this);

                return;
            }

            subscribedManager = stageManager;

            subscribedManager.StageGenerated +=
                OnStageGenerated;
        }

        /// <summary>
        /// ステージ生成イベントの登録を解除する。
        /// </summary>
        private void UnsubscribeStageEvents()
        {
            if (subscribedManager != null)
            {
                subscribedManager.StageGenerated -=
                    OnStageGenerated;
            }

            subscribedManager = null;
        }

        /// <summary>
        /// ステージ生成完了時のイベント処理。
        /// </summary>
        /// <param name="result">生成されたステージ情報</param>
        private void OnStageGenerated(
            MazeStageGenerationResult result)
        {
            if (!fitOnStageGenerated)
            {
                return;
            }

            FitCurrentStage();
        }

        #endregion

        #region Camera Methods

        /// <summary>
        /// 現在の迷路ステージにカメラを合わせる。
        /// </summary>
        /// <returns>調整に成功した場合はtrue</returns>
        public bool FitCurrentStage()
        {
            if (targetCamera == null ||
                stageManager == null ||
                !stageManager.HasStage ||
                stageManager.CoordinateConverter == null)
            {
                return false;
            }

            // 同一の画面比率でエラーが発生した場合に
            // 毎フレーム再試行することを防止する。
            lastAspect = targetCamera.aspect;

            try
            {
                GridCameraFitter.Fit(
                    targetCamera,
                    stageManager.CoordinateConverter,
                    stageManager.Map,
                    padding);

                if (printDebugLog)
                {
                    Debug.Log(
                        "【カメラ調整完了】\n" +
                        $"迷路サイズ：" +
                        $"{stageManager.Map.Width} × " +
                        $"{stageManager.Map.Height}\n" +
                        $"カメラ位置：" +
                        $"{targetCamera.transform.position}\n" +
                        $"Orthographic Size：" +
                        $"{targetCamera.orthographicSize:F3}\n" +
                        $"Aspect：{lastAspect:F3}",
                        this);
                }

                return true;
            }
            catch (Exception exception)
            {
                Debug.LogException(exception, this);

                return false;
            }
        }

        /// <summary>
        /// カメラ周囲の余白を変更する。
        /// </summary>
        /// <param name="newPadding">変更後の余白</param>
        /// <param name="refit">変更後に再調整するか</param>
        public void SetPadding(
            float newPadding,
            bool refit = true)
        {
            if (float.IsNaN(newPadding) ||
                float.IsInfinity(newPadding) ||
                newPadding < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(newPadding));
            }

            padding = newPadding;

            if (refit)
            {
                FitCurrentStage();
            }
        }

        /// <summary>
        /// Inspectorから手動でカメラを再調整する。
        /// </summary>
        [ContextMenu("カメラ/現在のステージに合わせる")]
        private void FitFromContextMenu()
        {
            if (!Application.isPlaying)
            {
                return;
            }

            FitCurrentStage();
        }

        #endregion
    }
}
